# General knowledge: everyday physics, chemistry and biology, health, space
# and technology, at Class 10 level. Static facts only. Key written first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Digestion", "The enzyme pepsin, made in the stomach, begins the digestion of which nutrient?",
      ["Proteins", "Starch", "Fats", "Fibre"],
      "Pepsin works in the acid of the stomach and breaks proteins into smaller peptides. Starch digestion begins in the mouth with salivary amylase, and fats are digested mainly in the small intestine."),
    S(1, 1, "Ecology", "Animals such as bears and crows, which eat both plants and animals, are called:",
      ["Omnivores", "Herbivores", "Carnivores", "Decomposers"],
      "Omnivores eat both plant and animal food. Herbivores eat only plants, carnivores only other animals, and decomposers break down dead matter."),
    S(1, 2, "Electricity", "What does a rectifier do?",
      ["Changes AC into DC", "Changes DC into AC", "Raises the AC voltage", "Stores electric charge"],
      "A rectifier, built from diodes, lets current pass one way only and so turns alternating current into direct current. An inverter does the reverse, and a step-up transformer raises AC voltage."),
    S(1, 1, "Space", "A solar eclipse happens when:",
      ["The Moon is between the Sun and Earth", "The Earth is between the Sun and Moon", "The Sun is between the Earth and Moon", "The Moon moves behind the Earth"],
      "In a solar eclipse the Moon blocks sunlight from part of the Earth, so it can only happen at new moon. When the Earth is between the Sun and the Moon, the result is a lunar eclipse."),
    S(1, 1, "Technology", "In an LED bulb, what does LED stand for?",
      ["Light Emitting Diode", "Low Energy Device", "Light Energy Detector", "Long Emission Display"],
      "An LED is a light emitting diode, a semiconductor that gives out light when current flows through it. It turns more of its energy into light than a filament bulb."),
    S(1, 2, "Nuclear energy", "What is the job of the control rods in a nuclear reactor?",
      ["Absorb extra neutrons", "Slow down fast neutrons", "Carry heat to the turbine", "Shield workers from rays"],
      "Control rods of boron or cadmium soak up neutrons, so pushing them in slows the chain reaction. Slowing neutrons down is the moderator's job, and the coolant carries the heat."),
    # ---------- Practice Test 2 ----------
    S(2, 1, "Biology", "Mycology is the scientific study of what?",
      ["Fungi", "Mosses", "Insects", "Birds"],
      "Mycology studies fungi such as mushrooms, moulds and yeasts. Insects are studied in entomology and birds in ornithology."),
    S(2, 2, "Human eye", "The rod cells in the retina of the eye mainly help us to:",
      ["See in dim light", "See colours clearly", "Focus on near objects", "Control the pupil size"],
      "Rod cells respond to low light but not to colour, which is why colours fade at dusk. Cone cells give colour vision in bright light, and the lens does the focusing."),
    S(2, 2, "Health", "Most kidney stones are made mainly of which compound?",
      ["Calcium oxalate", "Sodium chloride", "Calcium carbonate", "Uric acid crystals"],
      "About four in five kidney stones are calcium stones, mostly calcium oxalate. Uric acid stones are a smaller group, and calcium carbonate makes up shells and limestone."),
    S(2, 2, "Electricity", "What is the frequency of the AC mains supply in India?",
      ["50 Hz", "60 Hz", "100 Hz", "220 Hz"],
      "Indian mains supply alternates at 50 hertz, at a nominal 230 volts. Countries such as the USA use 60 Hz; 220 is a voltage figure, not a frequency."),
    S(2, 1, "Agriculture", "Growing pulses such as gram and lentil enriches the soil with which nutrient?",
      ["Nitrogen", "Phosphorus", "Potassium", "Calcium"],
      "Bacteria in the root nodules of pulse crops fix nitrogen from the air into compounds plants can use, so a pulse crop leaves the soil richer in nitrogen."),
    S(2, 1, "Light", "Which colour of visible light has the longest wavelength?",
      ["Red", "Violet", "Green", "Blue"],
      "Visible light runs from violet, about 400 nm, to red, about 700 nm. Red bends least in a prism because of its longer wavelength."),
    # ---------- Drill only ----------
    S(0, 1, "Space", "A lunar eclipse can occur only on which night?",
      ["A full moon night", "A new moon night", "A half moon night", "Any night of the month"],
      "A lunar eclipse needs the Earth exactly between the Sun and the Moon, which happens only when the Moon is full."),
    S(0, 1, "Nutrition", "Which of these vitamins dissolves in water rather than in fat?",
      ["Vitamin C", "Vitamin A", "Vitamin D", "Vitamin K"],
      "Vitamin C and the B vitamins are water-soluble, so the body does not store much of them. Vitamins A, D, E and K are fat-soluble."),
    S(0, 1, "Technology", "Malware is best described as:",
      ["Software made to cause harm", "A fault in computer hardware", "A program that speeds up a PC", "A backup of personal files"],
      "Malware, short for malicious software, includes viruses, worms, ransomware and spyware made to damage a device or steal data."),
    S(0, 2, "Technology", "A GPS receiver in a phone works out its position using signals from:",
      ["Satellites", "Mobile towers only", "Undersea cables", "Radio stations"],
      "GPS receivers time signals from several satellites in orbit and calculate their distance from each. Mobile towers can help but are not what GPS itself uses."),
    S(0, 2, "Earth science", "Which element is the most abundant in the Earth's crust by weight?",
      ["Oxygen", "Silicon", "Aluminium", "Iron"],
      "Oxygen makes up about 46% of the crust by weight, bound in rocks and minerals, followed by silicon at about 28%. Aluminium is the most abundant metal."),
    S(0, 2, "Work and energy", "A force of 12 N pushes a box 5 m in the direction of the force. How much work is done?",
      ["60 J", "2.4 J", "7 J", "17 J"],
      "Work = force x distance moved in the direction of the force = 12 x 5 = 60 joules. 17 adds the numbers and 2.4 divides them."),
    S(0, 2, "Electricity", "In a metal wire, an electric current is carried by:",
      ["Free electrons", "Protons", "Positive ions", "Neutrons"],
      "In metals some outer electrons are free to move, and their drift along the wire is the current. The positive ions stay fixed in the metal lattice."),
    S(0, 2, "Chemistry", "What does a catalyst do in a chemical reaction?",
      ["Changes its rate, unchanged itself", "Gets used up to give more product", "Always raises the temperature", "Changes which products form"],
      "A catalyst speeds up (or slows) a reaction without being used up, so it can be recovered at the end. It does not change the products or the amount formed."),
    S(0, 1, "Environment", "A person's or a product's carbon footprint is a measure of what?",
      ["Greenhouse gases released", "Carbon stored in forests", "Coal burnt in power plants", "Soot settling on buildings"],
      "A carbon footprint is the total of greenhouse gases, mainly carbon dioxide, released directly and indirectly by a person, product or organisation, usually given in tonnes of carbon dioxide equivalent."),
    S(0, 2, "Nutrition", "Marasmus, a wasting disease of young children, is caused mainly by a shortage of:",
      ["Overall food energy", "Vitamin C", "Iodine", "Iron"],
      "Marasmus comes from long-term lack of calories and nutrients overall, so the child wastes away. Kwashiorkor is linked mainly to protein shortage, scurvy to vitamin C and goitre to iodine."),
    S(0, 1, "Energy", "Which energy change takes place in a torch cell when it is in use?",
      ["Chemical to electrical", "Electrical to chemical", "Heat to electrical", "Light to chemical"],
      "A dry cell stores chemical energy and releases it as electrical energy. Charging a rechargeable battery does the reverse."),
    S(0, 1, "Agriculture", "Why are earthworms called the farmer's friend?",
      ["They loosen and enrich soil", "They eat harmful weeds", "They kill crop insects", "They pollinate crops"],
      "Burrowing earthworms loosen and aerate the soil and turn dead matter into rich castings. They do not pollinate or eat weeds."),
]
